+/** The arguments to `bun test`, which are paths. The command itself is not. */
+function pathsOf(command: string): string[] {
+  return command
+    .split(/\s+/)
+    .slice(2)
+    .filter((word) => word.startsWith("./") || word.startsWith("src/") || word.startsWith("tests/"));
