+      const hook = table[`pre${name}`];
+      if (!hook?.includes("synth")) {
+        offenders.push(
+          `\`${name}\` reads dist/ in ${readers.length} file(s), e.g. ${readers[0]}, and ` +
+            (hook ? `\`pre${name}\` is \`${hook}\`, which does not run \`synth\`` : `there is no \`pre${name}\` script`),
+        );
+      }
+    }
